CREATE TABLE IF NOT EXISTS case_payment_context (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid NOT NULL UNIQUE, user_id text NOT NULL, payment_rail text, upi_app text, upi_provider_key text, payer_bank text, payer_bank_key text, beneficiary_bank text, merchant_name text, payment_gateway text, card_issuer text, card_network text, acquirer text, context_source text NOT NULL DEFAULT 'CASE_FACTS', confidence numeric NOT NULL DEFAULT 0, needs_user_confirmation boolean NOT NULL DEFAULT false, raw_evidence jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS case_payment_context_user_idx ON case_payment_context(user_id,updated_at DESC);

CREATE TABLE IF NOT EXISTS bank_directory (bank_key text PRIMARY KEY, display_name text NOT NULL, aliases jsonb NOT NULL DEFAULT '[]'::jsonb, complaint_url text, official_url text, customer_care text, response_expectation_days integer, source_url text, active boolean NOT NULL DEFAULT true, updated_at timestamptz NOT NULL DEFAULT now());

